class SettlementCapacityPlanner {
    private static final Logger log = Logger.getLogger(SettlementCapacityPlanner.class.getName());

    // Binary search on capacity. O(n log(sum)) time.
    int minCapacity(int[] weights, int days) {
        int low = 0, high = 0;
        for (int w : weights) {
            low = Math.max(low, w);  // must hold the heaviest item
            high += w;               // one day ships everything
        }

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (daysNeeded(weights, mid) <= days) {
                final int m = mid;
                log.fine(() -> "Capacity " + m + " fits the day budget; trying smaller");
                high = mid;          // feasible: try smaller capacity
            } else {
                low = mid + 1;       // infeasible: need larger capacity
            }
        }
        return low;                  // minimum feasible capacity
    }

    // Greedy simulation: ship in order, new day when load would overflow.
    private int daysNeeded(int[] weights, int capacity) {
        int days = 1, load = 0;
        for (int w : weights) {
            if (load + w > capacity) {
                days++;              // close current day, start a new one
                load = 0;
            }
            load += w;
        }
        return days;
    }
}

